  const at=(a,c)=>{if(a.d===0)return a;if(c.d===0)return c;const key=[a.key,c.key].sort().join(':');if(intersections.has(key))return intersections.get(key);const t=a.d/(a.d-c.d),v={key,point:a.point.map((x,i)=>x+(c.point[i]-x)*t),d:0};intersections.set(key,v);return v;};
  function clip(poly,sign){const out=[];for(let i=0;i<poly.length;i++){const a=poly[i],c=poly[(i+1)%poly.length],ain=a.d*sign>=0,cin=c.d*sign>=0;if(ain)out.push(a);if(ain!==cin)out.push(at(a,c));}return out.filter((v,i)=>v.key!==out[(i+out.length-1)%out.length]?.key);}
