export function splitObject(object,normal=[1,0,0],offset=0,ratio=null){
  const mesh=bake(object),n=normalVector(normal);if(!closed(mesh)||signedVolume(mesh)<=1e-10)throw Error('부피 분할은 방향이 일관된 닫힌 표면에서 가능합니다.');
  const total=signedVolume(mesh);let distance=offset;
  if(ratio!==null){if(!Number.isFinite(ratio)||ratio<.01||ratio>.99)throw Error('A 부피 비율은 1–99%입니다.');let low=Infinity,high=-Infinity;for(let i=0;i<mesh.positions.length;i+=3){const d=dot(Array.from(mesh.positions.subarray(i,i+3)),n);low=Math.min(low,d);high=Math.max(high,d);}for(let i=0;i<20;i++){distance=(low+high)/2;let part;try{part=splitMesh(mesh,n,distance);}catch(e){if(e.message.includes('기존 면')){distance+=(high-low)*1e-5;part=splitMesh(mesh,n,distance);}else throw e;}const fraction=signedVolume(part[0])/total;if(Math.abs(fraction-ratio)<1e-6)break;if(fraction<ratio)low=distance;else high=distance;}}
  const pieces=splitMesh(mesh,n,distance);if(pieces.some(p=>!closed(p)))throw Error('절단면 연결 검사를 통과하지 못했습니다. 원본은 유지됩니다.');const first=signedVolume(pieces[0]),second=signedVolume(pieces[1]);if(first<=0||second<=0||Math.abs(first+second-total)>Math.max(total*1e-4,1e-7))throw Error('분할 부피 검사를 통과하지 못했습니다.');return {pieces,offset:distance,ratio:first/(first+second)};
}
